class Solution {
public:
    int uniqueLetterString(string s) {
        int n = s.size();
        vector<int> next(26,n);
        vector<int> nextIdx(n,n);
        vector<int> pre(26,-1);
        int ans = 0;
        for(int i = n - 1 ; i >= 0 ; i--){
            int pos = s[i] - 'A';
            if(next[pos] != n) nextIdx[i] = next[pos];   
            next[pos] = i;
        }
        for(int i = 0 ; i < n ; i++){
            int j = pre[s[i] - 'A'];
            ans += (i - j) * (nextIdx[i] - i);
            pre[s[i] - 'A'] = i;
        }

        return ans;
    }
};
